 "content": "def transform(grid):
    """Propagate each color along block rows/columns indicated by repeated markers."""
    h, w = len(grid), len(grid[0])
    row_divs = [r for r in range(h) if all(v == 8 for v in grid[r])]
    col_divs = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def segments(size, divs):
        result = []
        start = 0
        for divider in divs:
            if start < divider:
                result.append(list(range(start, divider)))
            start = divider + 1
        return result

    row_blocks = segments(h, row_divs)
    col_blocks = segments(w, col_divs)
    # Trailing margins, when present, are not compartments. Valid compartment
    # rows/columns end at the final divider and have the common block size.
    if row_blocks and len(row_blocks[-1]) != len(row_blocks[0]):
        row_blocks.pop()
    if col_blocks and len(col_blocks[-1]) != len(col_blocks[0]):
        col_blocks.pop()
    nr, nc = len(row_blocks), len(col_blocks)
    positions = {}
    for br, rows in enumerate(row_blocks):
        for bc, cols in enumerate(col_blocks):
            colors = {grid[r][c] for r in rows for c in cols if grid[r][c] not in (0, 8)}
            for color in colors:
                positions.setdefault(color, set()).add((br, bc))

    painted = [[0] * nc for _ in range(nr)]
    for color, pts in positions.items():
        row_counts = {}
        col_counts = {}
        for r, c in pts:
            row_counts[r] = row_counts.get(r, 0) + 1
            col_counts[c] = col_counts.get(c, 0) + 1
        full_rows = {r for r, count in row_counts.items() if count >= 2}
        full_cols = {c for c, count in col_counts.items() if count >= 2}
        for r in range(nr):
            for c in range(nc):
                if r in full_rows or c in full_cols:
                    painted[r][c] += color

    out = [row[:] for row in grid]
    for br, rows in enumerate(row_blocks):
        for bc, cols in enumerate(col_blocks):
            value = painted[br][bc]
            if value:
                for r in rows:
                    for c in cols:
                        out[r][c] = value
    return out
